95	/** AC 16 — clicking a thumbnail scrolls the stack to that image. */
96	export const ThumbnailNavigation: Story = {
97	  render: () => <OverlayHarness media={SEVEN_PHOTOS} />,
98	  play: async ({ canvasElement }) => {
99	    const canvas = within(canvasElement.ownerDocument.body);
100	    const thumb = await canvas.findByRole('button', { name: 'Go to image 4 of 7', hidden: true });
